import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.nextLine();
        List<Character> chars = new ArrayList<>();
        boolean foundAt = true;

        for (int position = 0; position < inputStr.length(); position++) {
            char currentChar = inputStr.charAt(position);
            if (position >= 2 && position < inputStr.length() && 
                inputStr.substring(position - 2, position + 1).equals("dot") && 
                position != inputStr.length() - 1 && position != 2) {
                if (!chars.isEmpty()) {
                    chars.remove(chars.size() - 1);
                }
                if (chars.size() >= 1) {
                    chars.remove(chars.size() - 1);
                }
                chars.add('.');
            } else if (position >= 1 && position < inputStr.length() && 
                       inputStr.substring(position - 1, position + 1).equals("at") && 
                       foundAt && position != 1 && position != inputStr.length() - 1) {
                if (!chars.isEmpty()) {
                    chars.remove(chars.size() - 1);
                }
                chars.add('@');
                foundAt = false;
            } else {
                chars.add(currentChar);
            }
        }

        StringBuilder resultStr = new StringBuilder();
        for (char c : chars) {
            resultStr.append(c);
        }
        System.out.println(resultStr.toString());
        scanner.close();
    }
}
